function submit(form,path,payload,reload){var cfg=data();if(!cfg.rest){return;}
var btn=form.querySelector('button[type="submit"]');if(btn){btn.disabled=true;}
fetch(cfg.rest+path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-WP-Nonce':cfg.nonce||''},body:JSON.stringify(payload)}).then(function(response){return response.json();}).then(function(json){if(!json||!json.ok){throw new Error((json&&json.message)||'failed');}
say(form,json.message,'ok');if(reload){window.location.reload();}}).catch(function(err){if(btn){btn.disabled=false;}
say(form,(err&&err.message)?err.message:(cfg.errorText||'انجام نشد.'),'error');});}
